# Suijin: `claude` runs under the Claude account selected in Suijin (bash).
# Generated by Suijin and rewritten when it changes.
#
# Every run re-reads $SUIJIN_DATA_ROOT/claude-profiles/selected-host (an absolute config directory), so switching accounts
# in Suijin applies to the next `claude` without reopening the terminal. An empty or missing pointer keeps your
# default login. A CLAUDE_CONFIG_DIR you set yourself wins, and so does a claude function you defined yourself: this file then
# defines nothing. Running under a Suijin account unsets API-key variables that would override its login.
#
# While it runs, the tab shows Claude with its status: the run is announced to Suijin (see the shell integration's
# __suijin_agent_begin), and Claude gets Suijin's hooks through `--settings`.
if ! typeset -f claude >/dev/null 2>&1; then
  function __suijin_claude_run {
    local __suijin_pointer __suijin_home=""
    local -a __suijin_settings=()
    # Suijin's hooks (`--settings`, merged with your own settings) report when Claude waits or finishes a turn.
    if [[ -n "${SUIJIN_CLAUDE_SETTINGS:-}" && -r "$SUIJIN_CLAUDE_SETTINGS" ]]; then
      __suijin_settings=(--settings "$SUIJIN_CLAUDE_SETTINGS")
    fi
    if [[ -n "${CLAUDE_CONFIG_DIR:-}" || -z "${SUIJIN_DATA_ROOT:-}" ]]; then
      command claude ${__suijin_settings[@]+"${__suijin_settings[@]}"} "$@"
      return
    fi
    __suijin_pointer="${SUIJIN_DATA_ROOT}/claude-profiles/selected-host"
    if [[ -r "$__suijin_pointer" ]]; then
      __suijin_home="$(cat -- "$__suijin_pointer" 2>/dev/null)"
    fi
    if [[ -z "$__suijin_home" ]]; then
      command claude ${__suijin_settings[@]+"${__suijin_settings[@]}"} "$@"
      return
    fi
    # Refuse rather than run under the wrong account.
    if [[ "$__suijin_home" != /* ]]; then
      printf '%s\n' "suijin: the selected Claude account is not an absolute path ($__suijin_pointer); claude not started." >&2
      return 1
    fi
    # A private folder, like the one Suijin creates for an account.
    [[ -d "$__suijin_home" ]] || mkdir -p -m 700 -- "$__suijin_home" 2>/dev/null
    (
      unset ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN AWS_BEARER_TOKEN_BEDROCK
      export CLAUDE_CONFIG_DIR="$__suijin_home"
      command claude ${__suijin_settings[@]+"${__suijin_settings[@]}"} "$@"
    )
  }
  # Tells Suijin that claude runs in this terminal, and when it is done. The prompt hook (__suijin_agent_prompt)
  # reports the end too when Ctrl-C or a crash skipped the last line.
  function claude {
    local __suijin_status
    __suijin_agent_begin claude
    __suijin_claude_run "$@"
    __suijin_status=$?
    __suijin_agent_end "$__suijin_status"
    return "$__suijin_status"
  }
fi
